namespace PZ3D {sealed partial class ModernController {
 sealed class OwnedCandidate {internal LauncherComponents.Row Row;internal string Token,Workshop;}
 sealed class OwnedChange {internal string Token,Operation,Stamp;}
 readonly Dictionary<string,OwnedChange> ownedChanges=new Dictionary<string,OwnedChange>();
 string OwnedSourceToken(string root,string id){return LauncherComponents.Hash(Encoding.UTF8.GetBytes(engine.OwnedConfiguration.Root+"\n"+Path.GetFullPath(root).ToUpperInvariant()+"\n"+id));}
 OwnedCandidate[] OwnedCandidates(List<string> scanWarnings=null){
  var service=engine.OwnedComponents();var selected=service.List(cancel.Token);var warnings=new List<string>();var budget=new LaunchReadBudget(67108864,100000);budget.Checkpoint=(file,size)=>cancel.Token.ThrowIfCancellationRequested();var catalog=SaveProfiles.SnapshotEntries(engine,new string[0],warnings,budget);var rows=new List<OwnedCandidate>();
  int inspected=0;foreach(var source in catalog.Candidates){cancel.Token.ThrowIfCancellationRequested();if(inspected++%20==0)Report(-1,"正在核对组件来源 · 已处理 "+(inspected-1)+" / "+catalog.Candidates.Count);try{var row=service.Inspect(source.Root,source.Id,cancel.Token);if(row.Jar==null&&!LauncherComponents.KnownIds.Contains(row.Id)&&!selected.Any(r=>r.Id==row.Id))continue;var current=selected.FirstOrDefault(r=>r.Id==row.Id&&VersionLibrary.Same(r.SourceRoot,row.SourceRoot));if(current!=null)row=current;rows.Add(new OwnedCandidate{Row=row,Token=OwnedSourceToken(row.SourceRoot,row.Id),Workshop=source.Workshop});}catch(OperationCanceledException){throw;}catch(Exception error){string metadata=Encoding.UTF8.GetString(source.Common??new byte[0])+Encoding.UTF8.GetString(source.Active??new byte[0]);if(LauncherComponents.KnownIds.Contains(source.Id)||metadata.IndexOf("javaJarFile",StringComparison.OrdinalIgnoreCase)>=0)rows.Add(new OwnedCandidate{Row=selected.FirstOrDefault(r=>r.Id==source.Id&&VersionLibrary.Same(r.SourceRoot,source.Root))??new LauncherComponents.Row{Id=source.Id,Name=source.Id,SourceRoot=source.Root,Warning=error.Message},Token=OwnedSourceToken(source.Root,source.Id),Workshop=source.Workshop});}}
  foreach(var row in selected)if(!rows.Any(x=>x.Row.Id==row.Id&&VersionLibrary.Same(x.Row.SourceRoot,row.SourceRoot)))rows.Add(new OwnedCandidate{Row=row,Token=OwnedSourceToken(row.SourceRoot,row.Id),Workshop=""});if(scanWarnings!=null){scanWarnings.AddRange(warnings);scanWarnings.AddRange(rows.Where(x=>!string.IsNullOrEmpty(x.Row.Warning)).Select(x=>x.Row.Id+"："+x.Row.Warning));if(budget.Incomplete&&scanWarnings.Count==0)scanWarnings.Add("部分来源未完整读取。");}return rows.GroupBy(x=>x.Token).Select(x=>x.First()).ToArray();
 }
 string OwnedInventoryStamp(OwnedCandidate[] rows){return LauncherComponents.Hash(Encoding.UTF8.GetBytes(string.Join("\n",rows.OrderBy(x=>x.Token).Select(x=>x.Token+"|"+x.Row.SourceEvidence+"|"+x.Row.ApprovalStamp+"|"+x.Row.Enabled+"|"+x.Row.Decision))));}
 JavaComponents.Row OwnedJavaRow(OwnedCandidate x){return new JavaComponents.Row{token=x.Token,modId=x.Row.Id,name=x.Row.Name,packageName=x.Row.Package,workshopId=x.Workshop,sourceKind=string.IsNullOrEmpty(x.Workshop)?"local":"workshop",sourceLabel=string.IsNullOrEmpty(x.Workshop)?x.Row.SourceRoot:"工坊 "+x.Workshop,enabled=x.Row.Enabled,canEnable=!x.Row.Enabled,canDisable=x.Row.Enabled,canUninstall=x.Row.Selected,jarState=x.Row.Warning!=""?"missing":x.Row.Jar==null?"none":"ready",approvalState=x.Row.Decision==true?"allowed":x.Row.Decision==false?"denied":"pending",requires=x.Row.Requires,limitations=x.Row.Warning==""?new string[0]:new[]{x.Row.Warning}};}
 object OwnedJavaList(string workshop=null){var warnings=new List<string>();var rows=OwnedCandidates(warnings);if(workshop!=null)rows=rows.Where(x=>x.Workshop==workshop).ToArray();return new{owned=true,stamp=OwnedInventoryStamp(rows),scannedUtc=DateTime.UtcNow.ToString("o"),incomplete=warnings.Count>0,warnings=warnings.Distinct().ToArray(),rows=rows.Select(OwnedJavaRow).ToArray()};}
 object OwnedApprovalList(){var rows=engine.OwnedComponents().List(cancel.Token).Where(r=>r.Enabled&&r.Jar!=null&&r.Id!="ZombieBuddy").ToArray();return new{supported=true,stamp=LauncherComponents.Hash(Encoding.UTF8.GetBytes(string.Join("\n",rows.Select(r=>r.ApprovalStamp+"|"+r.Decision)))),jars=rows.Select(r=>new{id=r.Id,name=r.Name,sha256=r.Sha256,approvalToken=r.ApprovalStamp,decision=r.Decision,warning=r.Warning}),warnings=new[]{"仅授权此启动配置所选的当前 Java 文件。"}};}
 object OwnedApprovalSave(Dictionary<string,object> p){object decision;if(!p.TryGetValue("decision",out decision)||!(decision is bool))throw new IOException("必须明确允许或拒绝此文件。");var rows=engine.OwnedComponents().List(cancel.Token).Where(r=>r.Enabled&&r.Jar!=null&&r.Id!="ZombieBuddy").ToArray();string stamp=LauncherComponents.Hash(Encoding.UTF8.GetBytes(string.Join("\n",rows.Select(r=>r.ApprovalStamp+"|"+r.Decision))));if(stamp!=Text(p,"stamp"))throw new IOException("Java 文件选择已变化，请刷新后授权。");var matches=rows.Where(r=>r.ApprovalStamp==Text(p,"hash")||r.Sha256==Text(p,"hash")).ToArray();if(matches.Length!=1)throw new IOException("当前 Java 文件无法唯一确认。");engine.OwnedComponents().Decide(matches[0].Id,matches[0].ApprovalStamp,(bool)decision,cancel.Token);return OwnedApprovalList();}
 static string OwnedComponentId(string key){switch(key){case "buddy":return "ZombieBuddy";case "base":case "viewpoint":return "Viewpoint";case "models":return "PZVoxelStudioViewpoint";case "shoot":return ShootClient.Id;case "chinese":return ChinesePatch.Id;}return ViewpointAddons.Get(key).Id;}
 static ulong OwnedComponentItem(string key){switch(key){case "buddy":return CoreComponents.Buddy;case "base":case "viewpoint":return CoreComponents.Viewpoint;case "models":return 3810302175;case "shoot":return ShootClient.Item;case "chinese":return ChinesePatch.Item;}return ViewpointAddons.Get(key).Item;}
 string OwnedComponentsAction(string key,string operation,Dictionary<string,object> p){
  if(engine.OwnedConfiguration.Mode=="vanilla")throw new IOException("原版配置不启用可选组件。");if(key=="all")return Batch(new[]{"base","models","shoot","chinese"},componentKey=>OwnedComponentsAction(componentKey,operation,p));
  string id=OwnedComponentId(key);var service=engine.OwnedComponents();if(operation=="uninstall"){Confirm(p);foreach(string remove in key=="base"?new[]{"Viewpoint","ZombieBuddy"}:new[]{id})service.Uninstall(remove,cancel.Token);return "已从此配置移除组件；原来源文件保留。";}
  if(operation!="install"&&operation!="update")throw new IOException("未知组件操作。");ulong item=OwnedComponentItem(key);string source=InstallWorkflow.Source(engine,item);if(operation=="update"||!Directory.Exists(source))source=Fetch(new[]{item},operation=="update")[item];
  string root=ViewpointAddons.ResolveSource(source,id,GameVersionProbe.Read(engine.Game)??new Version(42,0),new LaunchReadBudget(16777216),null).Folder;
  if(operation=="update"&&!service.List(cancel.Token).Any(r=>r.Id==id&&r.Enabled))return "已核对当前来源；此配置仍未启用该组件。";
  EnableOwnedRoot(root,id,new HashSet<string>(StringComparer.Ordinal));return "已在此配置启用 "+id+"。";
 }
 void EnableOwnedRoot(string root,string id,HashSet<string> visited){
  if(!visited.Add(id))return;cancel.Token.ThrowIfCancellationRequested();var service=engine.OwnedComponents();var row=service.Inspect(root,id,cancel.Token);
  foreach(string dependency in row.Requires.Concat(row.Jar!=null&&id!="ZombieBuddy"?new[]{"ZombieBuddy"}:new string[0]).Distinct()){
   if(service.List(cancel.Token).Any(r=>r.Id==dependency&&r.Enabled))continue;
   string known=dependency=="ZombieBuddy"?"buddy":dependency=="Viewpoint"?"viewpoint":dependency=="PZVoxelStudioViewpoint"?"models":dependency==ShootClient.Id?"shoot":dependency==ChinesePatch.Id?"chinese":ViewpointAddons.All.Where(a=>a.Id==dependency).Select(a=>a.Key).FirstOrDefault();
   var catalog=SaveProfiles.SnapshotEntries(engine,new[]{dependency},new List<string>(),new LaunchReadBudget(67108864,100000));var candidates=catalog.Candidates.Where(c=>c.Id==dependency).ToArray();
   if(candidates.Length==0){if(known!=null){ulong item=OwnedComponentItem(known);Fetch(new[]{item},false);}else{string workshop=ResolveSnapshotWorkshop(engine,new SaveEnvironmentMissing{modId=dependency},Report,cancel.Token);DownloadSnapshotWorkshop(engine,workshop,Report,cancel.Token);}catalog=SaveProfiles.SnapshotEntries(engine,new[]{dependency},new List<string>(),new LaunchReadBudget(67108864,100000));candidates=catalog.Candidates.Where(c=>c.Id==dependency).ToArray();}
   if(candidates.Length!=1)throw new IOException(dependency+"：缺少唯一可用来源，请选择此依赖后重试。");var inspected=service.Inspect(candidates[0].Root,dependency,cancel.Token);if(inspected.Jar!=null||LauncherComponents.KnownIds.Contains(dependency))EnableOwnedRoot(candidates[0].Root,dependency,visited);
  }
  service.Select(root,id,true,cancel.Token);
 }
 object OwnedJavaAction(string action,Dictionary<string,object> p){
  if(action=="javaComponentsList")return OwnedJavaList();var service=engine.OwnedComponents();
  if(action=="javaComponentsRecovery")return new JavaComponents.RecoveryResult{pending=false,supported=true,message="此配置没有待恢复组件事务。"};
  if(action=="javaComponentsReconcile"){Confirm(p);return new JavaComponents.Result{status="unchanged",message="此配置的组件选择独立保存。"};}
  if(action=="javaComponentsInspectDownloaded")return OwnedJavaList(Text(p,"id"));
  if(action=="javaComponentsInstall"){Confirm(p);DownloadSnapshotWorkshop(engine,Text(p,"id"),Report,cancel.Token);var rows=OwnedCandidates().Where(x=>x.Workshop==Text(p,"id")).ToArray();if(rows.Length!=1)return new JavaComponentWorkflow.Result{status=rows.Length==0?"unsupported":"selectionRequired",rows=rows.Select(OwnedJavaRow).ToArray(),message=rows.Length==0?"此项目未发现可启用的 Java 模组。":"请选择下载项目中要启用的 Java 模组。"};EnableOwnedRoot(rows[0].Row.SourceRoot,rows[0].Row.Id,new HashSet<string>());return new JavaComponents.Result{status="completed",changed=true,message="已在此配置启用所选 Java 模组。"};}
  if(action=="javaComponentsEnable"){Confirm(p);var found=OwnedCandidates().SingleOrDefault(x=>x.Token==Text(p,"token"));if(found==null)throw new IOException("所选来源已变化，请刷新。");EnableOwnedRoot(found.Row.SourceRoot,found.Row.Id,new HashSet<string>());return new JavaComponents.Result{status="completed",changed=true,message="已在此配置启用所选 Java 模组。"};}
  if(action=="javaComponentsPreview"){var rows=OwnedCandidates();string stamp=OwnedInventoryStamp(rows);if(stamp!=Text(p,"stamp"))throw new IOException("组件选择已变化，请刷新。");var row=rows.SingleOrDefault(x=>x.Token==Text(p,"token"));if(row==null)throw new IOException("组件来源已变化。");string op=Text(p,"operation");if(!new[]{"enable","disable","uninstall"}.Contains(op))throw new IOException("此配置支持启用、停用和移除选择。");if(op!="enable"&&!row.Row.Selected)throw new IOException("此来源不是当前配置所选组件，请刷新后选择已保存的来源。");string preview=Guid.NewGuid().ToString("N");ownedChanges[preview]=new OwnedChange{Token=row.Token,Operation=op,Stamp=stamp};return new JavaComponents.PreviewResult{supported=true,previewStamp=preview,operation=op,token=row.Token,name=row.Row.Name,message="仅修改此启动配置的组件选择。"};}
  if(action=="javaComponentsApply"){Confirm(p);OwnedChange plan;if(!ownedChanges.TryGetValue(Text(p,"previewStamp"),out plan))throw new IOException("组件预览已失效。");var rows=OwnedCandidates();if(OwnedInventoryStamp(rows)!=plan.Stamp)throw new IOException("组件来源或选择已变化，请重新预览。");var row=rows.Single(x=>x.Token==plan.Token);if(plan.Operation=="enable")EnableOwnedRoot(row.Row.SourceRoot,row.Row.Id,new HashSet<string>());else if(plan.Operation=="disable")service.SetEnabled(row.Row.Id,false,cancel.Token,row.Row.SourceRoot);else service.Uninstall(row.Row.Id,cancel.Token,row.Row.SourceRoot);ownedChanges.Remove(Text(p,"previewStamp"));return new JavaComponents.Result{status="completed",changed=true,message="已保存此配置的组件选择。"};}
  throw new IOException("此配置没有待恢复组件事务。");
 }
 object OwnedStatus(){var rows=engine.OwnedComponents().List(cancel.Token);Func<string,bool> enabled=id=>engine.OwnedConfiguration.Mode!="vanilla"&&rows.Any(r=>r.Id==id&&r.Enabled&&r.Warning=="");var cards=new[]{"buddy","viewpoint","base","models","shoot","chinese"}.Concat(ViewpointAddons.All.Select(a=>a.Key)).Select(key=>{string id=OwnedComponentId(key);var row=rows.FirstOrDefault(r=>r.Id==id);return (object)new{id=key,title=row==null?id:row.Name,description="此启动配置的独立组件选择。",item=OwnedComponentItem(key).ToString(),downloaded=row!=null&&row.Warning=="",configured=enabled(id),optional=key!="buddy"&&key!="base"&&key!="viewpoint",version="当前来源",warning=row==null?"":row.Warning};}).ToArray();cards=cards.Concat(rows.Where(row=>!LauncherComponents.KnownIds.Contains(row.Id)).Select(row=>(object)new{id=row.Id,title=row.Name,description="此配置所选的当前组件来源。",item="",downloaded=row.Warning=="",configured=engine.OwnedConfiguration.Mode!="vanilla"&&row.Enabled&&row.Warning=="",optional=true,version="当前来源",warning=row.Warning})).ToArray();return new{gamePath=engine.Game,gameVersion=LauncherStatusMetadata.GameVersion(engine.Game),validGame=LauncherLaunch.Reason(engine,false,false)=="",running=ClientRunning(),configured=enabled("Viewpoint"),buddyFiles=enabled("ZombieBuddy"),buddyRecovery=new{pending=false},configurationId=engine.LaunchConfiguration.Id,configurationName=engine.LaunchConfiguration.Name,configurationMode=engine.OwnedConfiguration.Mode,theme=LauncherTheme.Load(data).Light?"light":"dark",launch=LaunchProfiles.State(CurrentRuntimeEngine()),startup=StartupStatus(),hardware=test?HardwareProbe.Unknown():HardwareProbe.Cached(),task=new{active=busy,value=progressValue,text=progressText},components=cards,configStamp=HashPaths(new[]{engine.OwnedConfiguration.PreferencesPath,engine.Mods,Path.Combine(engine.OwnedConfiguration.ComponentsDirectory,"selection.json")})};}

